import math

def solve_quadratic(d1, d2, d3):
    # Equation: d3*p^2 + d2*p + d1 = 0
    # d1, d2, d3 are in {-2, 0, 2}
    solutions = set()

    if d3 == 0:
        # This case is handled separately as linear/constant, but we are focusing on quadratic via discriminant check per prompt.
        # Since we established d3 != 0 for the discriminant requirement, this should not happen.
        return set()

    # Discriminant calculation
    D = d2**2 - 4 * d3 * d1

    if D < 0:
        return set()

    sqrt_D = math.isqrt(D)
    if sqrt_D**2 != D:
        # D is not a perfect square, so solutions are not rational (assuming d_i are integers)
        return set()

    # Rational solutions exist
    for sign in [1, -1]:
        numerator = -d2 + sign * sqrt_D
        denominator = 2 * d3

        # Check for division by zero (already excluded d3=0)
        if denominator == 0:
            continue

        p = numerator / denominator

        # p must be positive and rational (which it is, as d_i are integers and D is a perfect square)
        if p > 0:
            # Store as a fraction or float representation that captures its nature
            # Since we are dealing with specific integer values, storing the float is fine for now, but we should verify if it's exactly rational.
            # Given the structure, if D is a perfect square, p is guaranteed rational.
            solutions.add(p)

    return solutions

possible_p = set()
D_vals = [-2, 0, 2]

# Iterate over d3 != 0
for d3 in [2, -2]:
    for d2 in D_vals:
        for d1 in D_vals:
            # Constraint: At least one d_i must be non-zero. 
            # Since d3 is non-zero, this is satisfied.

            solutions = solve_quadratic(d1, d2, d3)
            if solutions:
                for p in solutions:
                    # Rounding slightly to handle potential float representation issues near simple rationals, 
                    # but we must ensure we only capture distinct values.
                    possible_p.add(p)

# Convert set to list and sort for clean output
final_solutions = sorted(list(possible_p))

print("Found positive rational solutions p:")
for p in final_solutions:
    # Since p is derived from integer coefficients, it must be a ratio of integers.
    # We print it as a fraction representation if possible, or as a float if context requires simplicity.
    # Given the nature of the problem, exact rational form is preferred.
    # For presentation, printing the float rounded to high precision should suffice for verification, 
    # but we will list the derived numeric value.
    print(p)
